UItems.Sql:
SELECT  SumMember = COUNT(1)   FROM Member WHERE MType=0 And  AutoID IN (
SELECT MemberID FROM  QuestionResult WHERE CourseInfoID IN ( SELECT AutoID FROM  CourseInfo WHERE MemberID=@MemberID )
And QuestionItemID NOT IN ( SELECT AutoID FROM  QuestionItemInfo WHERE IsVal=1 )  );

SELECT  SumMember = COUNT(1)   FROM Member WHERE MType=0 And  AutoID IN (
SELECT MemberID FROM  QuestionResult WHERE CourseInfoID IN ( SELECT AutoID FROM  CourseInfo WHERE MemberID=@MemberID ) 
  AND CTime Between @begin And @end  ) ;

SELECT  SumMember = COUNT(1)   FROM Member WHERE MType=0 And  AutoID IN (
SELECT MemberID FROM  QuestionResult WHERE CourseInfoID IN ( SELECT AutoID FROM  CourseInfo WHERE MemberID=@MemberID )
And QuestionItemID NOT IN ( SELECT AutoID FROM  QuestionItemInfo WHERE IsVal=1 )  AND CTime Between @begin And @end  );

SELECT B.* FROM ( SELECT ROW_NUMBER() OVER(ORDER BY CTime desc) AS ROWNUM, * FROM School WHERE
1 = 1 @keyWord
) AS B WHERE ROWNUM > (@pageNo - 1) * @pageSize AND ROWNUM <= ((@pageNo - 1) + 1) * @pageSize  ORDER BY ROWNUM;

SELECT B.* FROM ( SELECT ROW_NUMBER() OVER(ORDER BY CTime desc) AS ROWNUM, * FROM NotifyInfo WHERE
MemberID = @MemberID
) AS B WHERE ROWNUM > (@pageNo - 1) * @pageSize AND ROWNUM <= ((@pageNo - 1) + 1) * @pageSize  ORDER BY ROWNUM;

SELECT COUNT(1) FROM  CourseInfo
WHERE RoomClassID=@RoomClassID And SubjectID=@SubjectID And  DocumentID NOT IN (
SELECT DocumentID   FROM  SourceDocument_Read WHERE  MemberID=@MemberID  )  ;

SELECT  A.* , B.TotalPage , ReadCount= ISNULL( C.ReadCount, 0)  FROM  (
SELECT * FROM CourseInfo  WHERE  QST_CourseID in ( [WhereIN]  )
) A
LEFT JOIN SourceDocument B ON B.AutoID = A.DocumentID
LEFT JOIN (SELECT DocumentID  , MemberID , ReadCount=COUNT(1) FROM  SourceDocument_Read   GROUP BY DocumentID , MemberID
) C ON C.DocumentID = A.DocumentID
WHERE  B.TotalPage >  ISNULL( C.ReadCount, 0)
ORDER BY CTime Desc ;

SELECT  A.* , B.TotalPage , ReadCount= ISNULL( C.ReadCount, 0) , TMemberID= C.MemberID FROM  (
SELECT * FROM CourseInfo
) A
LEFT JOIN SourceDocument B ON B.AutoID = A.DocumentID
LEFT JOIN (SELECT CourseID  , MemberID , ReadCount=COUNT(1) FROM  SourceDocument_Read   GROUP BY CourseID , MemberID
) C ON C.CourseID = A.AutoID
WHERE  B.TotalPage >  ISNULL( C.ReadCount, 0) And    C.MemberID=@MemberID
ORDER BY CTime Desc ;

SELECT  COUNT(1) FROM  CourseInfo A
LEFT JOIN SourceDocument B ON B.AutoID = A.DocumentID
LEFT JOIN (SELECT DocumentID  , MemberID , ReadCount=COUNT(1) FROM  SourceDocument_Read  WHERE  MemberID=@MemberID  GROUP BY DocumentID , MemberID
) C ON C.DocumentID = A.DocumentID
WHERE   B.TotalPage >  ISNULL( C.ReadCount, 0) ;
